const items = $input.all();
const today = new Date().toISOString().split('T')[0];

const projects = items.map(item => {
  const props = item.json.properties || {};
  const name = props['Name']?.title?.map(t => t.plain_text).join('') || 'Untitled';
  const status = props['Status']?.select?.name || 'Unknown';
  const progress = props['Progress']?.number || 0;
  const owner = props['Owner']?.rich_text?.map(t => t.plain_text).join('') || 'Unassigned';
  const dueDate = props['Due Date']?.date?.start || 'No deadline';
  return { name, status, progress, owner, dueDate };
});

const byStatus = {};
projects.forEach(p => {
  byStatus[p.status] = (byStatus[p.status] || 0) + 1;
});

const statusBreakdown = Object.entries(byStatus)
  .map(([status, count]) => `${status}: ${count}`)
  .join(', ');

const avgProgress = projects.length > 0
  ? Math.round(projects.reduce((sum, p) => sum + p.progress, 0) / projects.length)
  : 0;

const atRisk = projects.filter(p => {
  if (p.dueDate === 'No deadline') return false;
  const due = new Date(p.dueDate);
  const daysLeft = Math.ceil((due - Date.now()) / (1000 * 60 * 60 * 24));
  return daysLeft < 7 && p.progress < 80;
});

const detailedList = projects.map(p =>
  `• **${p.name}** — ${p.status} (${p.progress}%) — Owner: ${p.owner} — Due: ${p.dueDate}`
).join('\n');

const atRiskList = atRisk.length > 0
  ? atRisk.map(p => `⚠️ ${p.name} — ${p.progress}% — Due: ${p.dueDate}`).join('\n')
  : 'None';

return [{
  json: {
    date: today,
    totalProjects: projects.length,
    statusBreakdown,
    avgProgress,
    atRiskCount: atRisk.length,
    atRiskList,
    detailedList,
    summary: `Weekly Status Report — ${today}\n\nTotal Projects: ${projects.length}\nAvg Progress: ${avgProgress}%\nStatus: ${statusBreakdown}\nAt Risk: ${atRisk.length}`
  }
}];

